// Largest function start <= addr (containing function) or NULL.
static const char* GetFunctionNameAt(unsigned long addr)
{
    int lo = 0, hi = (int)(sizeof(kAddrFunc) / sizeof(kAddrFunc[0])) - 1, best = -1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (kAddrFunc[mid].addr <= addr) { best = mid; lo = mid + 1; }
        else { hi = mid - 1; }
    }
    return (best >= 0) ? kAddrFunc[best].name : NULL;
}

